    st.push(operand[i]);  // Push the current operand to the stack
    if (i < op.size()) {  // If there is an operator left
        if (op[i] == "+") {  // If the operator is addition
            long a = st.top();  // Pop the top element from the stack
            st.pop();
            long b = st.top();  // Pop the top element from the stack
            st.pop();
            st.push(a + b);  // Push the result of the addition to the stack
        } else if (op[i] == "-") {  // If the operator is subtraction
            long a = st.top();  // Pop the top element from the stack
            st.pop();
            long b = st.top();  // Pop the top element from the stack
            st.pop();
            st.push(b - a);  // Push the result of the subtraction to the stack
        } else if (op[i] == "*") {  // If the operator is multiplication
            long a = st.top();  // Pop the top element from the stack
            st.pop();
            long b = st.top();  // Pop the top element from the stack
            st.pop();
            st.push(a * b);  // Push the result of the multiplication to the stack
        } else if (op[i] == "//") {  // If the operator is floor division
            long a = st.top();  // Pop the top element from the stack
            st.pop();
            long b = st.top();  // Pop the top element from the stack
            st.pop();
            st.push(b / a);  // Push the result of the floor division to the stack
        } else if (op[i] == "**") {  // If the operator is exponentiation
            long a = st.top();  // Pop the top element from the stack
            st.pop();
            long b = st.top();  // Pop the top element from the stack
            st.pop();
            st.push(pow(b, a));  // Push the result of the exponentiation to the stack
        }
    }
}  // Return the result of the expression
return st.top();  // Return the result of the expression

